def solve(data):
    latest = {}
    for row in data['rows']:
        old = latest.get(row['id'])
        if old is None or row['revision'] > old['revision']:
            latest[row['id']] = row
    groups = {}
    for row in latest.values():
        if data.get('paid_only') and row['status'] != 'paid':
            continue
        groups.setdefault(row['team'], 0)
        if row['amount'] is not None:
            groups[row['team']] += row['amount']
    return [{'team': t, 'total': n} for t, n in sorted(groups.items())]

def solve(data):
    rows = sorted(data['rows'], key=lambda r: (r['id'], -r['revision']))
    unique = {}
