def solve(data):
    cursor, calls, items, ids, cursors = data['start'], [], [], set(), set()
    while True:
        if data.get('detect_cycles') and cursor in cursors:
            return {'items': items, 'calls': calls, 'error': 'cursor_cycle'}
        cursors.add(cursor)
        calls.append(cursor)
        page = data['pages'][cursor]
        for item in page['items']:
            if item['id'] not in ids:
                items.append(item)
                ids.add(item['id'])
        if not page['has_more']:
            break
        cursor = page['next']
    return {'items': items, 'calls': calls}

def solve(data):
    calls, unique = [], {}
    def visit(cursor):
        if data.get('detect_cycles') and cursor in calls:
            return 'cursor_cycle'
        calls.append(cursor)
        page = data['pages'][cursor]
        for item in page['items']:
            unique.setdefault(item['id'], item)
        return visit(page['next']) if page['has_more'] else None
    error = visit(data['start'])
    result = {'items': list(unique.values()), 'calls': calls}
    if error:
        result['error'] = error
    return result

